#include "lead_store.h"
#include "session.h"
#include <LittleFS.h>
#include <ArduinoJson.h>
static const char* PATH="/leads.ndjson"; static uint32_t countCached=0;
static bool safeText(const String&s,size_t n){return s.length()&&s.length()<=n&&s.indexOf('\n')<0&&s.indexOf('\r')<0;}
bool initLeadStore(){if(!LittleFS.begin(true))return false;recoverLeadStore();File f=LittleFS.open(PATH,"r");if(!f)return true;countCached=0;while(f.available())if(f.readStringUntil('\n').length())countCached++;f.close();return true;}
bool recoverLeadStore(){File f=LittleFS.open(PATH,"r");if(!f)return true;String line;bool ok=true;while(f.available()){line=f.readStringUntil('\n');if(line.length()>4096){ok=false;break;}}f.close();if(!ok){LittleFS.rename(PATH,"/leads.recovery");File n=LittleFS.open(PATH,"w");n.close();countCached=0;}return ok;}
bool validateLead(const Lead&l,String&e){if(!safeText(l.first,MAX_FIRST)){e="First name is required";return false;}if(l.last.length()>MAX_LAST||l.contact.length()>MAX_CONTACT||l.address.length()>MAX_ADDRESS||l.provider.length()>60||l.bill.length()>30||l.preferred.length()>20||l.interested.length()>4){e="A field is too long";return false;}if(!safeText(l.contact,MAX_CONTACT)){e="Phone or email is required";return false;}if(!l.consent){e="Consent is required";return false;}if(l.interested!="Yes"&&l.interested!="No"){e="Choose an information preference";return false;}return true;}
bool isDuplicateLead(const Lead&l){File f=LittleFS.open(PATH,"r");if(!f)return false;String line;while(f.available()){line=f.readStringUntil('\n');JsonDocument d;if(!deserializeJson(d,line)&&String((const char*)d["contact"])==l.contact&&String((const char*)d["firstName"])==l.first){f.close();return true;}}f.close();return false;}
bool appendLead(Lead&l,String&e){if(!validateLead(l,e))return false;if(isDuplicateLead(l)){e="This request was already received";return false;}if(LittleFS.usedBytes()+700>LittleFS.totalBytes()){e="Local storage is full";return false;}File f=LittleFS.open("/leads.tmp","a");if(!f){e="Storage write failed";return false;}l.sequence=++countCached;l.session=activeSessionId();l.createdMs=millis();JsonDocument d;d["schemaVersion"]=1;d["sequence"]=l.sequence;d["sessionId"]=l.session;d["firstName"]=l.first;d["lastName"]=l.last;d["contact"]=l.contact;d["address"]=l.address;d["provider"]=l.provider;d["monthlyBill"]=l.bill;d["preferredContact"]=l.preferred;d["interested"]=l.interested;d["consent"]=true;d["consentVersion"]="v1";d["createdMs"]=l.createdMs;size_t n=serializeJson(d,f);if(!n||!f.println()){f.close();e="Storage write failed";return false;}f.close();LittleFS.remove(PATH);if(!LittleFS.rename("/leads.tmp",PATH)){e="Storage commit failed";return false;}return true;}
uint32_t leadCount(){return countCached;}uint32_t pendingCount(){return countCached;}uint32_t todayCount(){return countCached;}bool eraseAllLeads(){return LittleFS.remove(PATH)||!LittleFS.exists(PATH);}
